def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    # Locate the full straight separator.
    sep = None
    for r, row in enumerate(grid):
        if all(v == 2 for v in row):
            sep = ('h', r)
            break
    if sep is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                sep = ('v', c)
                break
    if sep is None:
        return [row[:] for row in grid]

    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != background and grid[r][c] != 2]
    if not cells:
        return [row[:] for row in grid]

    out = [[background] * w for _ in range(h)]
    axis, pos = sep
    if axis == 'h':
        out[pos] = [2] * w
        top = min(r for r, c, v in cells)
        bottom = max(r for r, c, v in cells)
        # Move the object to touch the separator, preserving its orientation.
        dr = pos - 1 - bottom if bottom < pos else pos + 1 - top
        moved = [(r + dr, c, v) for r, c, v in cells]
        for r, c, v in moved:
            out[r][c] = v
        mark = min(r for r, c, v in moved) - 1 if bottom < pos else max(r for r, c, v in moved) + 1
        if 0 <= mark < h:
            out[mark] = [8] * w
    else:
        for r in range(h):
            out[r][pos] = 2
        leftmost = min(c for r, c, v in cells)
        rightmost = max(c for r, c, v in cells)
        dc = pos - 1 - rightmost if rightmost < pos else pos + 1 - leftmost
        moved = [(r, c + dc, v) for r, c, v in cells]
        for r, c, v in moved:
            out[r][c] = v
        mark = min(c for r, c, v in moved) - 1 if rightmost < pos else max(c for r, c, v in moved) + 1
        if 0 <= mark < w:
            for r in range(h):
                out[r][mark] = 8
    return out

